def acq_role_terms(text, spans):
    low = text.lower()
    segment = low
    extra = []
    markers = ('except in confidence to', 'except only to', 'except to', 'except its', 'except their', 'except such')
    for marker in markers:
        position = low.find(marker)
        if position >= 0:
            segment = low[position + len(marker):]
            break
    if segment == low and 'limited to those' in low:
        segment = low.split('limited to those', 1)[1]
    if segment == low and 'only to' in low:
        segment = low.split('only to', 1)[1]
    if segment == low and 'restrict access' in low and ' to ' in low:
        segment = low.rsplit(' to ', 1)[1]
    if segment == low and ('disclose' in low or 'divulge' in low or 'reveal' in low) and ' to ' in low:
        segment = low.rsplit(' to ', 1)[1]
    if 'representative' in segment and not any(token in segment for token in ('employee', 'officer', 'director', 'consultant', 'contractor', 'agent', 'adviser', 'advisor')):
        for span in spans:
            if not isinstance(span, dict) or type(span.get('id')) is not int or not isinstance(span.get('text'), str):
                continue
            candidate = span.get('text').lower()
            if 'representative' in candidate and ('collectively' in candidate or ' means ' in candidate) and any(token in candidate for token in ('employee', 'officer', 'director', 'consultant', 'contractor', 'agent', 'adviser', 'advisor')):
                segment += ' ' + candidate
                extra.append(span.get('id'))
                break
    receiver = ['receiving_party']
    parts = []
    role_map = [('employees_of', ('employee', 'members of its staff', 'members of staff', 'personnel')), ('officers_of', ('officer',)), ('directors_of', ('director',)), ('consultants_of', ('consultant',)), ('independent_contractors_of', ('contractor',)), ('agents_of', ('agent',)), ('professional_advisors_of', ('professional adviser', 'professional advisor')), ('legal_advisors_of', ('legal adviser', 'legal advisor', 'attorney', 'legal counsel')), ('financial_advisors_of', ('financial adviser', 'financial advisor')), ('accountants_of', ('accountant',)), ('lenders_of', ('lender',))]
    for constructor, words in role_map:
        if any(word in segment for word in words):
            parts.append([constructor, receiver])
    if 'affiliate' in segment:
        parts.append(['affiliates_of', receiver])
    if 'subsidiar' in segment or 'controlled entit' in segment:
        parts.append(['controlled_entities_of', receiver])
    if any(token in segment for token in ('third party', 'third-party', 'third parties', 'any other person', 'any other party', 'any person or entity', 'anyone')):
        parts.append(['third_parties'])
    return [legal_union(parts), extra]

def acq_condition_term(text):
    low = text.lower()
    terms = []
    if any(token in low for token in ('need to know', 'need-to-know', 'strict need to know')):
        terms.append(['need_to_know', text])
    if any(token in low for token in ('strictly necessary', 'extent necessary', 'necessary for the purpose', 'necessary in pursuit', 'involved in the performance', 'required for use by')):
        terms.append(['extent_necessary', text])
    if any(token in low for token in ('bound in writing', 'agreed to be bound in writing', 'written confidentiality agreement', 'obligated to protect', 'obliged by their contracts', 'subject to written confidentiality', 'terms no less stringent', 'terms no less protective')):
        terms.append(['confidentiality_bound', text])
    if not terms:
        return ['no_condition']
    out = terms[0]
    i = 1
    while i < len(terms):
        out = ['and_condition', out, terms[i]]
        i += 1
    return out

def acq_emit_prohibition(queries, answers, fragments, unit, supports, text, permitted):
    low = text.lower()
    identity = 'program:clause-frame:prohibition:' + str(unit)
    legal_add_query(queries, answers, identity, 'source_clause_kind', supports, 'source_prohibition')
    recipient = ['third_parties']
    if permitted is not None:
        recipient = ['outsiders_to', permitted]
    legal_add_fragment(fragments, ['disclose', ['confidential_information'], recipient], supports, [identity])
    legal_add_fragment(fragments, ['no_condition'], supports, [identity])
    if permitted is not None:
        exception = ['no_exceptions']
    elif 'written consent' in low or 'written approval' in low:
        exception = ['exception_set', ['authorization_exception', text]]
    elif any(token in low for token in ('course of service', 'performance of the project', 'performing the services', 'fulfilling its obligations')):
        exception = ['exception_set', ['purpose_exception', text]]
    elif any(token in low for token in ('except as provided', 'unless this agreement expressly permits', 'other than as permitted')):
        exception = ['exception_set', ['cross_reference_exception', text]]
    else:
        exception = ['no_exceptions']
    legal_add_fragment(fragments, exception, supports, [identity])

def acq_disposal_action(text, material):
    low = text.lower()
    has_return = 'return' in low
    has_destroy = any(token in low for token in ('destroy', 'delete', 'erase'))
    returned = ['return_to', material, ['disclosing_party']]
    destroyed = ['destroy', material]
    if has_return and has_destroy:
        if any(token in low for token in ('; and', ' and destroy', ' and permanently erase')) and not any(token in low for token in (' or destroy', ' or permanently erase')):
            return ['source_action_conjunction', returned, destroyed, text]
        if any(token in low for token in ('expressly authorised in writing', 'expressly authorized in writing')):
            return ['source_authorized_action_alternative', returned, destroyed, text]
        if any(token in low for token in ("at discloser's option", 'at your option', "at sintec's option", 'as directed by the disclosing party', "at auditee's discretion")):
            return ['source_action_alternative', returned, destroyed, text]
        return ['action_alternative', returned, destroyed]
    if has_return:
        return returned
    if has_destroy:
        return destroyed
    return None
